//! The Greyhaven region's design (#816): the macro terrain beyond the hand-authored core
//! (`content/greyhaven/terrain.json`, generated by `content/greyhaven/authoring/region_design.py`)
//! and the rivers, lakes and roads the zone shapes into it (`content/greyhaven/design.json`).
//! Both files are committed content, parsed once; the design is in metres, the zone in units.
use std::collections::BTreeMap;
use std::sync::LazyLock;

use serde::Deserialize;

use crate::{Terrain, WaterChannel, WaterVolume};

const DESIGN: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../content/greyhaven/design.json"
));
const TERRAIN: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../content/greyhaven/terrain.json"
));

#[derive(Deserialize)]
struct Source {
    version: u32,
    rivers: Vec<RiverSource>,
    lakes: Vec<LakeSource>,
    #[serde(default)]
    roads: Vec<RoadSource>,
    #[serde(default)]
    forests: Vec<ForestSource>,
    #[serde(default)]
    rockfields: Vec<RockfieldSource>,
    heart: Vec<[f64; 2]>,
}

#[derive(Deserialize)]
struct RockfieldSource {
    name: String,
    spacing: f64,
    cover: u8,
    polygon: Vec<[f64; 2]>,
}

/// A designed field of boulders: its outline, spacing (units), cover (percent of cells with a
/// boulder) and seed.
pub struct Rockfield {
    pub name: String,
    pub spacing: i32,
    pub cover: u8,
    pub polygon: Vec<[i32; 2]>,
    pub seed: u64,
}

#[derive(Deserialize)]
struct ForestSource {
    name: String,
    species: Species,
    spacing: f64,
    cover: u8,
    polygon: Vec<[f64; 2]>,
}

/// What grows in a forest: its trees' kinds, chosen per trunk by the clients (#816).
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum Species {
    /// Mostly pines.
    Pine,
    /// Pines, oaks and birches.
    Mixed,
    /// Mostly oaks and birches.
    Broadleaf,
}

/// A designed forest: its outline, spacing (units), cover (percent of cells with a trunk),
/// species and seed.
pub struct Forest {
    pub name: String,
    pub species: Species,
    pub spacing: i32,
    pub cover: u8,
    pub polygon: Vec<[i32; 2]>,
    pub seed: u64,
}

impl Forest {
    /// The outline's bounding rectangle `[min, max]`.
    #[must_use]
    pub fn bounds(&self) -> [[i32; 2]; 2] {
        let mut bounds = [[i32::MAX; 2], [i32::MIN; 2]];
        for point in &self.polygon {
            for axis in 0..2 {
                bounds[0][axis] = bounds[0][axis].min(point[axis]);
                bounds[1][axis] = bounds[1][axis].max(point[axis]);
            }
        }
        bounds
    }

    /// Whether `(x, z)` lies inside the outline (even–odd rule).
    #[must_use]
    pub fn contains(&self, x: i32, z: i32) -> bool {
        polygon_contains(&self.polygon, x, z)
    }
}

/// Whether `(x, z)` lies inside `polygon` (even–odd rule).
#[must_use]
pub fn polygon_contains(polygon: &[[i32; 2]], x: i32, z: i32) -> bool {
    let mut inside = false;
    for index in 0..polygon.len() {
        let a = polygon[index];
        let b = polygon[(index + 1) % polygon.len()];
        if (a[1] > z) == (b[1] > z) {
            continue;
        }
        let (dz, dx) = (i64::from(b[1] - a[1]), i64::from(b[0] - a[0]));
        let lhs = (i64::from(x) - i64::from(a[0])) * dz;
        let rhs = (i64::from(z) - i64::from(a[1])) * dx;
        if (dz > 0 && lhs < rhs) || (dz < 0 && lhs > rhs) {
            inside = !inside;
        }
    }
    inside
}

#[derive(Deserialize)]
struct RiverSource {
    name: String,
    width: f64,
    points: Vec<[f64; 2]>,
}

#[derive(Deserialize)]
struct LakeSource {
    name: String,
    centre: [f64; 2],
    radii: [f64; 2],
    surface: f64,
}

#[derive(Deserialize)]
struct RoadSource {
    name: String,
    points: Vec<[f64; 2]>,
}

#[derive(Deserialize)]
struct TerrainSource {
    version: u32,
    origin: [i32; 2],
    step: i32,
    columns: u16,
    rows: u16,
    heights: Vec<Vec<i32>>,
}

/// A river: its centre line downstream in units, its channel's half width and its reaches.
pub struct River {
    pub name: String,
    pub points: Vec<[i32; 2]>,
    pub half_width: i32,
    pub reaches: Vec<Reach>,
}

/// A stretch of river at one surface: its centre line, surface and span along the river.
pub struct Reach {
    pub points: Vec<[i32; 2]>,
    pub surface: i32,
    pub from: i64,
    pub to: i64,
}

/// A lake: an elliptical water at a fixed surface.
pub struct Lake {
    pub name: String,
    pub centre: [i32; 2],
    pub radii: [i32; 2],
    pub surface: i32,
}

/// A designed road: its name and centre line in units.
pub struct DesignRoad {
    pub name: String,
    pub points: Vec<[i32; 2]>,
}

pub struct Design {
    /// The macro terrain beyond the hand-authored core, in units.
    pub terrain: Terrain,
    pub rivers: Vec<River>,
    pub lakes: Vec<Lake>,
    pub roads: Vec<DesignRoad>,
    pub forests: Vec<Forest>,
    pub rockfields: Vec<Rockfield>,
    /// The hand-authored heart's outline (#816), rounded into curves, in units.
    pub heart: Vec<[i32; 2]>,
}

/// A stable seed from a name.
fn seed_of(name: &str) -> u64 {
    name.bytes().fold(0xcbf2_9ce4_8422_2325_u64, |hash, byte| {
        (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3)
    })
}

/// River surfaces drop by at most this much between consecutive reaches.
const REACH_DROP_UNITS: i32 = 120;
/// A river channel's bed lies this far below its surface.
pub const RIVER_DEPTH_UNITS: i32 = 70;
/// The current of every designed river (units per second).
const RIVER_CURRENT: i32 = 60;

fn units(metres: f64) -> i32 {
    // Design coordinates stay far inside the content range.
    #[allow(clippy::cast_possible_truncation)]
    {
        (metres * 100.0).round() as i32
    }
}

fn line(points: &[[f64; 2]]) -> Vec<[i32; 2]> {
    points.iter().map(|p| [units(p[0]), units(p[1])]).collect()
}

/// A closed outline rounded into curves: three rounds of corner cutting all the way round.
fn rounded(points: &[[f64; 2]]) -> Vec<[i32; 2]> {
    let mut outline = points.to_vec();
    for _ in 0..3 {
        let mut cut = Vec::with_capacity(outline.len() * 2);
        for index in 0..outline.len() {
            let (a, b) = (outline[index], outline[(index + 1) % outline.len()]);
            cut.push([a[0] * 0.75 + b[0] * 0.25, a[1] * 0.75 + b[1] * 0.25]);
            cut.push([a[0] * 0.25 + b[0] * 0.75, a[1] * 0.25 + b[1] * 0.75]);
        }
        outline = cut;
    }
    line(&outline)
}

/// A centre line rounded into curves (#816): two rounds of corner cutting, keeping its ends, so
/// a road or river bends instead of turning at each authored point.
fn curved(points: &[[f64; 2]]) -> Vec<[i32; 2]> {
    let mut line = points.to_vec();
    for _ in 0..2 {
        if line.len() < 3 {
            break;
        }
        let mut cut = vec![line[0]];
        for pair in line.windows(2) {
            let (a, b) = (pair[0], pair[1]);
            cut.push([a[0] * 0.75 + b[0] * 0.25, a[1] * 0.75 + b[1] * 0.25]);
            cut.push([a[0] * 0.25 + b[0] * 0.75, a[1] * 0.25 + b[1] * 0.75]);
        }
        cut.push(line[line.len() - 1]);
        line = cut;
    }
    let mut out: Vec<[i32; 2]> = Vec::with_capacity(line.len());
    for point in self::line(&line) {
        if out.last() != Some(&point) {
            out.push(point);
        }
    }
    out
}

fn length(a: [i32; 2], b: [i32; 2]) -> i64 {
    let (dx, dz) = (i64::from(b[0] - a[0]), i64::from(b[1] - a[1]));
    i64::try_from((dx * dx + dz * dz).unsigned_abs().isqrt()).unwrap_or(0)
}

/// A river cut into reaches of one surface each, the lowest along the reach so the water never
/// stands above its banks; consecutive reaches step down by at most [`REACH_DROP_UNITS`]. A
/// point's surface is the macro ground less 0.4 m, never rising downstream.
fn reaches(terrain: &Terrain, points: &[[i32; 2]]) -> Vec<Reach> {
    // Each point's surface: the lowest ground along the river so far, sampled every 4 m so the
    // water never stands above a dip between two points.
    let mut lowest = i32::MAX;
    let mut surfaces = Vec::with_capacity(points.len());
    for (index, point) in points.iter().enumerate() {
        if index > 0 {
            let from = points[index - 1];
            let steps = (length(from, *point) / 400).max(1);
            for step in 1..steps {
                let at = |a: i32, b: i32| {
                    a + i32::try_from(i64::from(b - a) * step / steps).unwrap_or(0)
                };
                lowest = lowest
                    .min(smooth_height(terrain, at(from[0], point[0]), at(from[1], point[1])) - 40);
            }
        }
        lowest = lowest.min(smooth_height(terrain, point[0], point[1]) - 40);
        surfaces.push(lowest);
    }
    let mut along = vec![0_i64];
    for pair in points.windows(2) {
        along.push(along[along.len() - 1] + length(pair[0], pair[1]));
    }
    let mut out = Vec::new();
    let mut start = 0;
    while start + 1 < points.len() {
        let top = surfaces[start];
        let mut end = start + 1;
        while end + 1 < points.len() && top - surfaces[end + 1] <= REACH_DROP_UNITS {
            end += 1;
        }
        out.push(Reach {
            points: points[start..=end].to_vec(),
            surface: surfaces[end],
            from: along[start],
            to: along[end],
        });
        start = end;
    }
    out
}

fn parse(design: &str, terrain: &str) -> Result<Design, String> {
    let source: Source = serde_json::from_str(design).map_err(|error| error.to_string())?;
    if source.version != 1 {
        return Err(format!("unknown design version {}", source.version));
    }
    let grid: TerrainSource = serde_json::from_str(terrain).map_err(|error| error.to_string())?;
    if grid.version != 1
        || grid.heights.len() != usize::from(grid.rows)
        || grid
            .heights
            .iter()
            .any(|row| row.len() != usize::from(grid.columns))
    {
        return Err("terrain.json does not match its size".to_owned());
    }
    let terrain = Terrain {
        origin: grid.origin,
        step: grid.step,
        columns: grid.columns,
        rows: grid.rows,
        heights: grid.heights.into_iter().flatten().collect(),
    };
    terrain.validate().map_err(|error| error.to_string())?;
    let rivers = source
        .rivers
        .into_iter()
        .map(|river| {
            let points = curved(&river.points);
            River {
                name: river.name,
                reaches: reaches(&terrain, &points),
                points,
                half_width: units(river.width / 2.0),
            }
        })
        .collect();
    let lakes = source
        .lakes
        .into_iter()
        .map(|lake| Lake {
            name: lake.name,
            centre: [units(lake.centre[0]), units(lake.centre[1])],
            radii: [units(lake.radii[0]), units(lake.radii[1])],
            surface: units(lake.surface),
        })
        .collect();
    let mut roads: Vec<DesignRoad> = source
        .roads
        .into_iter()
        .map(|road| DesignRoad {
            name: road.name,
            points: curved(&road.points),
        })
        .collect();
    // A road ending within 8 m of another, as a branch does, ends on that road's curve.
    for index in 0..roads.len() {
        for end in [0, roads[index].points.len() - 1] {
            let [x, z] = roads[index].points[end];
            let snapped = roads
                .iter()
                .enumerate()
                .filter(|(other, _)| *other != index)
                .filter_map(|(_, other)| nearest_point(&other.points, x, z))
                .filter(|(distance, _)| *distance <= 800)
                .min_by_key(|(distance, _)| *distance);
            if let Some((_, point)) = snapped {
                roads[index].points[end] = point;
            }
        }
    }
    let forests = source
        .forests
        .into_iter()
        .map(|forest| Forest {
            seed: seed_of(&forest.name),
            name: forest.name,
            species: forest.species,
            spacing: units(forest.spacing),
            cover: forest.cover.min(100),
            polygon: line(&forest.polygon),
        })
        .collect();
    let rockfields = source
        .rockfields
        .into_iter()
        .map(|field| Rockfield {
            seed: seed_of(&field.name),
            name: field.name,
            spacing: units(field.spacing),
            cover: field.cover.min(100),
            polygon: line(&field.polygon),
        })
        .collect();
    if source.heart.len() < 3 {
        return Err("the heart needs an outline".to_owned());
    }
    Ok(Design {
        terrain,
        rivers,
        lakes,
        roads,
        forests,
        rockfields,
        heart: rounded(&source.heart),
    })
}

static DATA: LazyLock<Design> =
    LazyLock::new(|| parse(DESIGN, TERRAIN).expect("committed Greyhaven design is valid"));

/// The committed design.
#[must_use]
pub fn data() -> &'static Design {
    &DATA
}

/// The heart's outline reaches up to this much (15 m) further out where the noise swells it.
const HEART_SWELL_UNITS: i64 = 1_500;

/// The heart outline's bounding rectangle, grown by the swell.
static HEART_BOUNDS: LazyLock<[[i32; 2]; 2]> = LazyLock::new(|| {
    let mut bounds = [[i32::MAX; 2], [i32::MIN; 2]];
    for point in &data().heart {
        for axis in 0..2 {
            bounds[0][axis] = bounds[0][axis].min(point[axis]);
            bounds[1][axis] = bounds[1][axis].max(point[axis]);
        }
    }
    let swell = i32::try_from(HEART_SWELL_UNITS).unwrap_or(0);
    [
        bounds[0].map(|value| value - swell),
        bounds[1].map(|value| value + swell),
    ]
});

/// Units from `(x, z)` to the hand-authored heart (#816): positive outside it, zero or negative
/// inside. The heart is its rounded outline, swollen outwards by up to [`HEART_SWELL_UNITS`] in
/// broad lobes so its edge never runs in one smooth line.
#[must_use]
pub fn heart_distance(x: i32, z: i32) -> i64 {
    let [min, max] = *HEART_BOUNDS;
    let outside = i64::from((min[0] - x).max(x - max[0]).max(0))
        .max(i64::from((min[1] - z).max(z - max[1]).max(0)));
    // Far from the heart a lower bound on the distance is enough.
    if outside > 20_000 {
        return outside;
    }
    let outline = &data().heart;
    // The square root is monotonic, so the nearest edge's root is the polyline distance's minimum
    // at one root per sample instead of two per edge (#855).
    let edge = outline
        .iter()
        .zip(outline.iter().cycle().skip(1))
        .map(|(&a, &b)| segment_distance2(a, b, x, z).0)
        .min()
        .map_or(i64::MAX, root);
    if polygon_contains(outline, x, z) {
        return -edge;
    }
    let swell = super::value_noise_q10(i64::from(x), i64::from(z), 5_000, 0x0048_4541_5254)
        * HEART_SWELL_UNITS
        / 1_024;
    (edge - swell).max(1)
}

impl River {
    /// The water surface a distance `along` the river (units).
    #[must_use]
    pub fn surface_at(&self, along: i64) -> i32 {
        self.reaches
            .iter()
            .find(|reach| along <= reach.to)
            .or(self.reaches.last())
            .map_or(0, |reach| reach.surface)
    }
}

/// The designed waters: each lake, and each river reach as a channel.
#[must_use]
pub fn water_volumes() -> Vec<WaterVolume> {
    let design = data();
    let mut volumes: Vec<WaterVolume> = design
        .lakes
        .iter()
        .map(|lake| WaterVolume {
            channel: None,
            name: lake.name.clone(),
            centre: lake.centre,
            radii: lake.radii,
            surface: lake.surface,
            air_pockets: Vec::new(),
        })
        .collect();
    for river in &design.rivers {
        for (index, reach) in river.reaches.iter().enumerate() {
            volumes.push(WaterVolume {
                channel: Some(WaterChannel {
                    points: reach.points.clone(),
                    half_width: river.half_width,
                    current: RIVER_CURRENT,
                }),
                name: format!("{} {}", river.name, index + 1),
                // The channel supplies the footprint; these mark its start for validation.
                centre: reach.points[0],
                radii: [river.half_width, river.half_width],
                surface: reach.surface,
                air_pockets: Vec::new(),
            });
        }
    }
    volumes
}

/// A river's banks rise from its water's edge at 1:2 to the ground within this reach.
const BANK_UNITS: i32 = 1_000;
/// Ground lies level under a pad and returns to the landscape across this apron.
const PAD_APRON_UNITS: i64 = 600;

static RIVERS: LazyLock<LineIndex> = LazyLock::new(|| {
    let design = data();
    let reach = design
        .rivers
        .iter()
        .map(|river| river.half_width + BANK_UNITS)
        .max()
        .unwrap_or(0);
    LineIndex::new(
        design.rivers.iter().map(|river| river.points.as_slice()),
        4_000,
        reach,
    )
});

/// The macro terrain's height at `(x, z)`, interpolated by Catmull–Rom splines through its
/// 16 m samples so its slopes bend smoothly instead of creasing at every sample line (#816).
#[must_use]
pub fn macro_height(x: i32, z: i32) -> i32 {
    smooth_height(&data().terrain, x, z)
}

fn smooth_height(terrain: &Terrain, x: i32, z: i32) -> i32 {
    let step = i64::from(terrain.step);
    let (columns, rows) = (i64::from(terrain.columns), i64::from(terrain.rows));
    let fx = i64::from(x - terrain.origin[0]);
    let fz = i64::from(z - terrain.origin[1]);
    let (column, row) = (fx.div_euclid(step), fz.div_euclid(step));
    // Fractions in Q10.
    let (tx, tz) = (
        fx.rem_euclid(step) * 1_024 / step,
        fz.rem_euclid(step) * 1_024 / step,
    );
    let sample = |c: i64, r: i64| {
        let c = usize::try_from(c.clamp(0, columns - 1)).unwrap_or(0);
        let r = usize::try_from(r.clamp(0, rows - 1)).unwrap_or(0);
        i64::from(terrain.heights[r * usize::from(terrain.columns) + c])
    };
    // Catmull–Rom weights of the four samples round a fraction `t` (Q10), summing to 1024³.
    let weights = |t: i64| {
        let (t2, t3) = (t * t, t * t * t);
        let one = 1_024_i64;
        [
            (-t3 + 2 * t2 * one - t * one * one) / 2,
            (3 * t3 - 5 * t2 * one + 2 * one * one * one) / 2,
            (-3 * t3 + 4 * t2 * one + t * one * one) / 2,
            (t3 - t2 * one) / 2,
        ]
    };
    let (wx, wz) = (weights(tx), weights(tz));
    let mut sum = 0_i64;
    for (j, wj) in wz.iter().enumerate() {
        let mut across = 0_i64;
        for (i, wi) in wx.iter().enumerate() {
            let offset = |k: usize| i64::try_from(k).unwrap_or(0) - 1;
            across += sample(column + offset(i), row + offset(j)) * wi;
        }
        sum += across / (1_024 * 1_024) * wj;
    }
    i32::try_from(sum / (1_024 * 1_024 * 1_024 * 1_024)).unwrap_or(0)
}

/// The macro terrain with the rivers' channels cut into it: a bed [`RIVER_DEPTH_UNITS`] below
/// each reach's surface across the channel, and banks rising from just above the water.
fn carved(x: i32, z: i32) -> i32 {
    let design = data();
    let mut ground = macro_height(x, z);
    for &index in RIVERS.near(x, z) {
        let river = &design.rivers[index];
        let (distance, along) = polyline_distance(&river.points, x, z);
        let surface = river.surface_at(along);
        let half = i64::from(river.half_width);
        if distance <= half {
            ground = ground.min(surface - RIVER_DEPTH_UNITS);
        } else if distance <= half + i64::from(BANK_UNITS) {
            let bank = i64::from(surface) + 30 + (distance - half) / 2;
            ground = ground.min(i32::try_from(bank).unwrap_or(ground));
        }
    }
    ground
}

/// Units from `(x, z)` to the nearest river channel's edge (zero or less in a channel), as far as
/// any river's banks reach; `i64::MAX` beyond them.
#[must_use]
pub fn river_distance(x: i32, z: i32) -> i64 {
    let design = data();
    RIVERS
        .near(x, z)
        .iter()
        .map(|&index| {
            let river = &design.rivers[index];
            polyline_distance(&river.points, x, z).0 - i64::from(river.half_width)
        })
        .min()
        .unwrap_or(i64::MAX)
}

/// Whether `(x, z)` lies in a designed lake or within `margin` units of its shore.
#[must_use]
pub fn in_lake(x: i32, z: i32, margin: i32) -> bool {
    data().lakes.iter().any(|lake| {
        let dx = i128::from(x) - i128::from(lake.centre[0]);
        let dz = i128::from(z) - i128::from(lake.centre[1]);
        let rx = i128::from(lake.radii[0] + margin);
        let rz = i128::from(lake.radii[1] + margin);
        dx * dx * rz * rz + dz * dz * rx * rx <= rx * rx * rz * rz
    })
}

/// Whether `(x, z)` lies on a pad ([`ground`]) or within `margin` units of one.
#[must_use]
pub fn on_pad(x: i32, z: i32, margin: i32) -> bool {
    PADS.iter().any(|pad| {
        x >= pad.min[0] - margin
            && x <= pad.max[0] + margin
            && z >= pad.min[1] - margin
            && z <= pad.max[1] + margin
    })
}

/// The first designed forest that grows at `(x, z)`: its outline, wobbled by up to about 20 m,
/// holds the point and the point lies outside the forest's glades. Trunks stand only where
/// their forest grows, and clients draw forest floor there.
#[must_use]
pub fn forest_at(x: i32, z: i32) -> Option<&'static Forest> {
    let (x64, z64) = (i64::from(x), i64::from(z));
    let warp = |seed: u64| (super::value_noise_q10(x64, z64, 6_000, seed) - 512) * 4;
    let wx = i32::try_from(x64 + warp(0x5741_5250_0001)).unwrap_or(x);
    let wz = i32::try_from(z64 + warp(0x5741_5250_0002)).unwrap_or(z);
    data().forests.iter().find(|forest| {
        forest.contains(wx, wz) && super::value_noise_q10(x64, z64, 3_200, forest.seed) >= 330
    })
}

/// What a region collider is (#816), for clients to draw it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RegionBody {
    /// A designed forest's trunk, of the forest's species there.
    Trunk(Option<Species>),
    /// A rock field's boulder.
    Boulder,
}

/// Whether `collider` is one of the region's trunks or boulders, and which.
#[must_use]
pub fn region_body(collider: &crate::StaticCollider) -> Option<RegionBody> {
    let [x, _, z] = collider.position;
    if super::ids::REGION_TREES.contains(&collider.id) {
        Some(RegionBody::Trunk(species_at(x, z)))
    } else if super::ids::REGION_BOULDERS.contains(&collider.id) {
        Some(RegionBody::Boulder)
    } else {
        None
    }
}

/// The species of the forest growing at `(x, z)`, if one does.
#[must_use]
pub fn species_at(x: i32, z: i32) -> Option<Species> {
    forest_at(x, z).map(|forest| forest.species)
}

/// A footprint the ground lies level under, at the carved ground's height at its centre.
struct Pad {
    min: [i32; 2],
    max: [i32; 2],
    height: i32,
}

/// The region's yards, fields and buildings beyond the core: each a pad (#816). Yards, hamlets
/// and fields lie level at the carved ground's height at their centre; a building that touches
/// one shares its height, so a yard and its palisade or a hamlet and its houses stand level
/// together, and any other building lies level at its own centre's height.
static PADS: LazyLock<Vec<Pad>> = LazyLock::new(|| {
    let areas: Vec<Pad> = super::farmland::LEVEL
        .iter()
        .chain(&super::farmland::FIELDS)
        .copied()
        .chain([super::highlands::STRONGHOLD, super::highlands::LOOKOUT])
        .chain(
            super::settlements::SETTLEMENTS
                .iter()
                .map(|settlement| settlement.yard),
        )
        .map(|(min, max)| Pad {
            min,
            max,
            height: carved((min[0] + max[0]) / 2, (min[1] + max[1]) / 2),
        })
        .collect();
    let buildings = super::farmland::BUILDINGS
        .iter()
        .map(|&(_, min, max, _)| (min, max))
        .chain(
            super::highlands::BUILDINGS
                .iter()
                .map(|&(_, min, max, _)| (min, max)),
        )
        .chain(
            super::marsh::BUILDINGS
                .iter()
                .map(|&(_, min, max, _)| (min, max)),
        )
        .chain(super::settlements::structures().map(|(_, min, max, _)| (min, max)));
    let touching = |min: [i32; 2], max: [i32; 2]| {
        areas.iter().find(|area| {
            min[0] <= area.max[0] + 200
                && max[0] >= area.min[0] - 200
                && min[1] <= area.max[1] + 200
                && max[1] >= area.min[1] - 200
        })
    };
    let buildings: Vec<Pad> = buildings
        .map(|(min, max)| Pad {
            min,
            max,
            height: touching(min, max).map_or_else(
                || carved((min[0] + max[0]) / 2, (min[1] + max[1]) / 2),
                |area| area.height,
            ),
        })
        .collect();
    areas.into_iter().chain(buildings).collect()
});

/// The designed landscape's ground at `(x, z)` (#816): the macro terrain, its rivers, the pads
/// under the region's structures and the wetlands' own waters.
#[must_use]
pub fn ground(x: i32, z: i32) -> i32 {
    let mut ground = carved(x, z);
    for pad in PADS.iter() {
        let dx = (pad.min[0] - x).max(x - pad.max[0]).max(0);
        let dz = (pad.min[1] - z).max(z - pad.max[1]).max(0);
        let distance = i64::from(dx.max(dz));
        if distance < PAD_APRON_UNITS {
            let weight = 1_024 - super::smooth_q10(distance, 0, PAD_APRON_UNITS);
            ground += i32::try_from(i64::from(pad.height - ground) * weight / 1_024).unwrap_or(0);
        }
    }
    if let Some((water, weight)) = super::marsh::water_ground(x, z) {
        ground += i32::try_from(i64::from(water - ground) * weight / 1_024).unwrap_or(0);
    }
    ground
}

/// The distance (units) from `(x, z)` to a polyline and the polyline's nearest point.
fn nearest_point(points: &[[i32; 2]], x: i32, z: i32) -> Option<(i64, [i32; 2])> {
    points
        .windows(2)
        .map(|pair| {
            let [ax, az] = pair[0].map(i64::from);
            let [bx, bz] = pair[1].map(i64::from);
            let (vx, vz) = (bx - ax, bz - az);
            let length2 = (vx * vx + vz * vz).max(1);
            let t = (((i64::from(x) - ax) * vx + (i64::from(z) - az) * vz) * 1_024 / length2)
                .clamp(0, 1_024);
            let point = [
                i32::try_from(ax + vx * t / 1_024).unwrap_or(x),
                i32::try_from(az + vz * t / 1_024).unwrap_or(z),
            ];
            let (dx, dz) = (i64::from(x - point[0]), i64::from(z - point[1]));
            (
                i64::try_from((dx * dx + dz * dz).unsigned_abs().isqrt()).unwrap_or(i64::MAX),
                point,
            )
        })
        .min_by_key(|(distance, _)| *distance)
}

/// Distance (units) from `(x, z)` to a polyline, and the distance along it of the nearest point.
#[must_use]
pub fn polyline_distance(points: &[[i32; 2]], x: i32, z: i32) -> (i64, i64) {
    let mut best = (i64::MAX, 0);
    let mut run = 0_i64;
    for pair in points.windows(2) {
        let (distance2, t) = segment_distance2(pair[0], pair[1], x, z);
        let distance = root(distance2);
        let segment = length(pair[0], pair[1]);
        if distance < best.0 {
            best = (distance, run + segment * t / 1_024);
        }
        run += segment;
    }
    best
}

/// The squared distance (units²) from `(x, z)` to segment `a`–`b`, and the nearest point's
/// position along it in 1/1024ths, as [`polyline_distance`] measures it.
fn segment_distance2(a: [i32; 2], b: [i32; 2], x: i32, z: i32) -> (u64, i64) {
    let [ax, az] = a.map(i64::from);
    let [bx, bz] = b.map(i64::from);
    let (vx, vz) = (bx - ax, bz - az);
    let length2 = (vx * vx + vz * vz).max(1);
    let (px, pz) = (i64::from(x) - ax, i64::from(z) - az);
    let t = ((px * vx + pz * vz) * 1_024 / length2).clamp(0, 1_024);
    let (cx, cz) = (ax + vx * t / 1_024, az + vz * t / 1_024);
    let (dx, dz) = (i64::from(x) - cx, i64::from(z) - cz);
    ((dx * dx + dz * dz).unsigned_abs(), t)
}

/// The distance (units) of a squared distance from [`segment_distance2`].
fn root(distance2: u64) -> i64 {
    i64::try_from(distance2.isqrt()).unwrap_or(i64::MAX)
}

/// Polyline segments bucketed on a coarse grid, so a point finds the lines near it quickly.
pub struct LineIndex {
    cell: i32,
    buckets: BTreeMap<(i32, i32), Vec<usize>>,
}

impl LineIndex {
    /// Indexes `lines`, each under every bucket within `reach` of it.
    #[must_use]
    pub fn new<'a>(lines: impl Iterator<Item = &'a [[i32; 2]]>, cell: i32, reach: i32) -> Self {
        let mut buckets: BTreeMap<(i32, i32), Vec<usize>> = BTreeMap::new();
        for (index, points) in lines.enumerate() {
            for pair in points.windows(2) {
                let lo = [
                    pair[0][0].min(pair[1][0]) - reach,
                    pair[0][1].min(pair[1][1]) - reach,
                ];
                let hi = [
                    pair[0][0].max(pair[1][0]) + reach,
                    pair[0][1].max(pair[1][1]) + reach,
                ];
                for bx in lo[0].div_euclid(cell)..=hi[0].div_euclid(cell) {
                    for bz in lo[1].div_euclid(cell)..=hi[1].div_euclid(cell) {
                        let entry = buckets.entry((bx, bz)).or_default();
                        if entry.last() != Some(&index) {
                            entry.push(index);
                        }
                    }
                }
            }
        }
        Self { cell, buckets }
    }

    /// The lines that may lie within the index's reach of `(x, z)`.
    #[must_use]
    pub fn near(&self, x: i32, z: i32) -> &[usize] {
        self.buckets
            .get(&(x.div_euclid(self.cell), z.div_euclid(self.cell)))
            .map_or(&[], Vec::as_slice)
    }
}

#[cfg(test)]
mod tests {
    use super::{data, polyline_distance};

    #[test]
    fn the_committed_design_parses_and_its_rivers_fall_downstream() {
        let design = data();
        assert!(!design.rivers.is_empty() && !design.lakes.is_empty());
        for river in &design.rivers {
            let surfaces: Vec<i32> = river.reaches.iter().map(|reach| reach.surface).collect();
            assert!(
                surfaces.windows(2).all(|pair| pair[1] <= pair[0]),
                "{}",
                river.name
            );
        }
        assert_eq!(
            polyline_distance(&[[0, 0], [1_000, 0]], 500, 300),
            (300, 500)
        );
    }
}
